package com.aistock.common.marketrefs;
import javax.sql.DataSource;import java.sql.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static com.aistock.common.marketrefs.MarketReferenceRecords.*;
class ReferenceScannerTest {
 final String v="11111111-1111-1111-1111-111111111111";final Source source=new Source("snapshot","引用记录","safe_records",List.of("version_id"),List.of());
 @Test void emptyWholeTableIsKnownZeroAndConnectionIsRolledBackAndClosed()throws Exception{var ds=mock(DataSource.class);var c=mock(Connection.class);var st=mock(PreparedStatement.class);var rs=mock(ResultSet.class);when(ds.getConnection()).thenReturn(c);when(c.prepareStatement(anyString())).thenReturn(st);when(st.executeQuery()).thenReturn(rs);when(rs.next()).thenReturn(true);var scanner=new ReferenceScanner(ds,"prediction",List.of(source),Clock.systemUTC());var result=scanner.scan(v);assertEquals("COMPLETE",result.state());assertEquals("0",result.groups().get(0).rows());verify(c).setReadOnly(true);verify(c).setAutoCommit(false);verify(c).rollback();verify(c).close();verify(st).setQueryTimeout(1);}
 @Test void connectionFailureIsUnknownNeverZeroAndDoesNotExposeSql()throws Exception{var ds=mock(DataSource.class);when(ds.getConnection()).thenThrow(new SQLException("private schema and password"));var result=new ReferenceScanner(ds,"prediction",List.of(source),Clock.systemUTC()).scan(v);assertEquals("UNKNOWN",result.state());assertTrue(result.groups().isEmpty());assertEquals("REFERENCE_QUERY_UNAVAILABLE",result.reasonCode());}
 @Test void busyScannerDoesNotQueueOrAcquireSecondConnection()throws Exception{var ds=mock(DataSource.class);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);when(ds.getConnection()).thenAnswer(a->{entered.countDown();release.await(5,TimeUnit.SECONDS);throw new SQLException("closed");});var scanner=new ReferenceScanner(ds,"prediction",List.of(source),Clock.systemUTC());var executor=Executors.newSingleThreadExecutor();try{var first=executor.submit(()->scanner.scan(v));assertTrue(entered.await(5,TimeUnit.SECONDS));var busy=scanner.scan(v);assertEquals("REFERENCE_QUERY_BUSY",busy.reasonCode());verify(ds,times(1)).getConnection();release.countDown();first.get(5,TimeUnit.SECONDS);scanner.scan(v);verify(ds,times(2)).getConnection();}finally{release.countDown();executor.shutdownNow();}}
}
